css:
.cat-badge{display:inline-flex;align-items:center;gap:5px;height:19px;padding:0 8px;border-radius:var(--cat-size-radius-pill);font:600 var(--cat-font-size-2xs) var(--cat-font-family-ui);letter-spacing:.03em;background:rgba(0,0,0,.07);color:var(--cat-color-ink-mid)}
.cat-badge.accent{background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));color:#fff}
.cat-badge.success{background:var(--cat-color-success);color:#fff}
.cat-badge.danger{background:var(--cat-color-danger-base);color:#fff}
.cat-badge .dot{width:7px;height:7px;border-radius:50%;background:currentColor}
[data-cat-tooltip]{position:relative}
[data-cat-tooltip]::after{content:attr(data-cat-tooltip);position:absolute;bottom:calc(100% + 7px);left:50%;transform:translateX(-50%) translateY(2px);padding:4px 9px;border-radius:var(--cat-size-radius-sm);background:var(--cat-color-ink-hi);color:#fff;font:500 var(--cat-font-size-xs) var(--cat-font-family-ui);white-space:nowrap;opacity:0;pointer-events:none;transition:opacity var(--cat-motion-fast) ease,transform var(--cat-motion-fast) var(--cat-motion-ease-out);z-index:var(--cat-depth-z-dropdown)}
[data-cat-tooltip]:hover::after,[data-cat-tooltip]:focus-within::after{opacity:1;transform:translateX(-50%) translateY(0)}
.cat-kbd{display:inline-block;padding:1px 6px;border-radius:var(--cat-size-radius-xs);border:1px solid var(--cat-color-stroke-dark);background:rgba(0,0,0,.05);box-shadow:inset 0 -1.5px 0 rgba(0,0,0,.08);font:500 var(--cat-font-size-xs) var(--cat-font-family-mono);color:var(--cat-color-ink-mid)}
.cat-divider{height:1px;background:var(--cat-color-stroke-dark);border:none;margin:12px 0}
.cat-divider.v{width:1px;height:18px;margin:0 8px;align-self:center}
.cat-avatar{position:relative;width:32px;height:32px;border-radius:50%;background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));color:#fff;display:grid;place-items:center;font:600 var(--cat-font-size-sm) var(--cat-font-family-ui);overflow:visible}
.cat-avatar img{width:100%;height:100%;border-radius:50%;object-fit:cover}
.cat-avatar .presence{position:absolute;bottom:-1px;right:-1px;width:10px;height:10px;border-radius:50%;background:var(--cat-color-success);border:2px solid #fff}
